chat_template:
{#- Llama-3 chat INFERENCE template — same rendering as llama3_training.jinja
    but without {% generation %} markers (vLLM/llama.cpp jinja engines don't
    know that tag). sft_train.py writes this into the saved tokenizer.
    NOTE: unlike the training template, this does NOT emit bos_token. Serving
    engines / notebooks tokenize the rendered string with add_special_tokens=True,
    so the tokenizer already prepends <|begin_of_text|>. Emitting it here too
    caused a DOUBLE BOS (<|begin_of_text|><|begin_of_text|>). The training
    template keeps bos_token because TRL tokenizes with add_special_tokens=False.
    Matches mii-llm/nesso-0.4B-instruct convention (template has no bos). -#}
{%- for message in messages -%}
{{- '<|start_header_id|>' + message['role'] + '<|end_header_id|>\n\n' + (message['content'] | trim) + '<|eot_id|>' -}}
{%- endfor -%}
{%- if add_generation_prompt -%}
{{- '<|start_header_id|>assistant<|end_header_id|>\n\n' -}}
{%- endif -%}
